1	/**
2	 * Wires every subscriber at process start. Called once from `src/instrumentation.ts`; the only module that knows the full listener set.
3	 *
4	 * Must call (do not reimplement): subscribe, registerActivityListeners, registerSearchListeners, registerUsageListeners, registerWebhookListeners
5	 */
6	import { subscribe } from "@/lib/event-bus";
7	import { createLogger } from "@/lib/logger";
8	import { enqueue } from "@/server/jobs/queue";
9	import { toIsoTimestamp } from "@/types/common";
10	import { registerActivityListeners } from "./activity-service";
11	import { registerSearchListeners } from "./search-service";
12	import { registerUsageListeners } from "./usage-service";
13	import { registerWebhookListeners } from "./webhook-service";
14	import type { Unsubscribe } from "@/types/event";
15	
16	/**
17	 * Importing this module also loads `notification-service` transitively, which
18	 * attaches the notification fan-out on first import — that hub has no
19	 * `register*` entry point of its own.
20	 */
21	import "./notification-service";
22	
23	const logger = createLogger("event-registry");
24	
25	/** Non-null between `registerEventHandlers()` and `unregisterEventHandlers()`. */
26	let detach: Unsubscribe | null = null;
27	
28	/**
29	 * Attaches every subscriber exactly once. Idempotent: `instrumentation.ts`
30	 * runs per server process, but a hot reload in dev can call it again and must
31	 * not double-deliver every event.
32	 */
33	export function registerEventHandlers(): void {
34	  if (detach !== null) return;
35	
36	  const offs: Unsubscribe[] = [
37	    registerActivityListeners(),
38	    registerSearchListeners(),
39	    registerUsageListeners(),
40	    registerWebhookListeners(),
41	    registerDigestBridge(),
42	  ];
43	
44	  detach = () => {
45	    for (const off of offs) off();
46	  };
47	
48	  logger.info("event handlers registered", { groups: offs.length });
49	}
50	
51	export function unregisterEventHandlers(): void {
52	  detach?.();
53	  detach = null;
54	}
55	
56	/**
57	 * The one piece of wiring that belongs to no single service: turning a
58	 * `digest.due` event into a queued job. Keeping it here rather than inside
59	 * `DigestService` stops the service layer from depending on the job layer.
60	 */
61	function registerDigestBridge(): Unsubscribe {
62	  return subscribe("digest.due", (payload) => {
63	    enqueue({
64	      id: `digest:${payload.orgId}:${payload.recipientId}`,
65	      kind: "digest-email",
66	      runAt: toIsoTimestamp(new Date()),
67	      attempts: 0,
